function withTimeout<T>(promise:Promise<T>,ms:number,message:string):Promise<T>{let timer:number|undefined;return Promise.race([promise,new Promise<T>((_,reject)=>{timer=window.setTimeout(()=>reject(new Error(message)),ms)})]).finally(()=>{if(timer!==undefined)window.clearTimeout(timer)})}
