function useServices(){const [items,setItems]=useState<Service[]>(starter);useEffect(()=>{if(!hasFirebaseWebConfig)return;return onSnapshot(collection(db,"services"),s=>{const allIds=new Set(s.docs.map(d=>d.id));const legacyIds=new Set(["gates","security","trailers","carports","bunks","laser","custom"]);const rows=s.docs.map(d=>({id:d.id,...d.data(),price:null} as Service)).filter(x=>x.active!==false&&!legacyIds.has(x.id)&&typeof x.name==="string"&&typeof x.description==="string"&&cats.slice(1).includes(x.category));setItems([...rows,...starter.filter(seed=>!allIds.has(seed.id))])},()=>setItems(starter))},[]);return items}
function useBasket(){const [items,setItems]=useState<Line[]>([]);useEffect(()=>{try{setItems(JSON.parse(localStorage.getItem(key)||"[]"))}catch{setItems([])}},[]);function save(n:Line[]){setItems(n);try{localStorage.setItem(key,JSON.stringify(n))}catch{}}return {items,add:(s:Service)=>{track("service_added_to_quote",{category:s.category});const old=items.find(x=>x.serviceId===s.id);save(old?items.map(x=>x.serviceId===s.id?{...x,quantity:Math.min(99,x.quantity+1)}:x):[...items,{serviceId:s.id,name:s.name,category:s.category,price:s.price,quantity:1}])},remove:(id:string)=>save(items.filter(x=>x.serviceId!==id)),qty:(id:string,n:number)=>save(items.map(x=>x.serviceId===id?{...x,quantity:Math.min(99,n)}:x).filter(x=>x.quantity>0)),clear:()=>save([])}}
function Header({count=0,home=false}:{count?:number;home?:boolean}){return <><div className="af-topline"><span>BOTSWANA · VIP EVENT SANITATION</span><span>Comfort and hygiene for your event</span></div><header className="af-header"><Link href="/" className="af-brand"><span className="af-brand-mark">RB<span>✦</span></span><span><strong>RB CONSULTANCY</strong><small>VIP TOILET HIRE</small></span></Link><nav>{!home&&<><Link href="/services">Services</Link><Link href="/#work">Unit gallery</Link><Link href="/account">My RB Consultancy</Link></>}</nav><div className="af-head-actions">{!home&&<Link className="af-basket-link" href="/basket">My quote request <span>{count}</span></Link>}{home&&<Link className="af-button af-button-outline af-button-small" href="/account">My RB Consultancy</Link>}<Link className="af-button af-button-small" href="/enquiry">{home?"Request an event quote ↗":"Get a quote ↗"}</Link></div></header></>}
